from pathlib import Path
from collections import Counter
import gzip,hashlib,json
D=Path(__file__).resolve().parent
def read(n):return json.loads((D/n).read_bytes())
def pct(x):return f"{100*x:.2f}".replace(".",",")
def dformat(x):return f"{100*x:+.2f}".replace(".",",")
def dec(x):return f"{x:.1f}".replace(".",",")
frozen=read("frozen_before_scoring.json")
assert all(hashlib.sha256(Path(p).read_bytes()).hexdigest()==s for p,s in frozen.items())
ds=read("results.json");receipt=read("selection_receipt.json");down=read("download_summary.json");times=read("timings.json");rec=read("receipts.json")
n=ds["n"]; names={"lru":"LRU","point":"Точечная","typed":"Граф соседних блоков","mixed":"Переключатель по размеру свежего просмотра"}
with gzip.open(D/"scored.jsonl.gz","rt",encoding="utf8") as f:rows=[json.loads(z) for z in f]
projects=sorted({r[1] for r in rows}); assert len(rows)==n and n<=ds["audit"]["cuts"]
gate=Counter();con=Counter()
for tm in times:gate.update(tm["gate_calls"])
for r in rec:
    if r["status"]=="ok":con.update(r["counts"])
released=[r for r in rec if r["status"]!="ok"];used=sum(r["status"]=="ok" for r in rec);ev=ds["audit"]["events"];total=ds["audit"]["cuts"]
notes=["# Выбор между давностью доступа и графом по размеру свежего просмотра","","## Вопрос и постановка","",f"Проверено одно заранее зафиксированное изменение политики вытеснения на второй группе SWE-bench Verified. В исходном каталоге человеческих issues хеш-отбор дал {len(rec)} новых задач из {len(receipt['repo'])} проектов. Отбор задач проведён до чтения их траекторий. С первой группой из 165 идентификаторов пересечений нет, проекты повторяются. Получено {used} проекций редактора. Отбор не учитывал успех агента. Из {total} четырёхшаговых контрольных точек в {n} последовала подтверждённая правка, её адрес и точные строки однозначно известны для {ds['unique']}. Остальные {n-ds['unique']} остались в знаменателе с нулевым баллом для всех. Отдельных задач с оцениваемым срезом {ds['issues']}.","","У каждого варианта один восстанавливаемый бинарный снимок, максимум 4096 байт после каждого события. Новый вариант ведёт тот же объём метаданных, что граф. При переполнении он определяет размер всего пакета наиболее свежих страниц. Когда их несжатый текст с адресами помещается в 4096 байт, правило отдаёт приоритет страницам по давности доступа, применяя LRU. Иначе свежий доступ охватывает слишком большой объём, и граф ранжирует соседей при вытеснении. Последней датой просмотра страницы считается наиболее поздняя дата среди её строк в блоке из 12, полный размер — реально сериализованное состояние. Правило использовало фиксированный размер устройства, не подбирало веса или порог.","","## Что осталось в памяти","","| Политика | Полная правка | Средняя доля строк | Первая строка | Средний / максимум байт | мс на событие* |","|---|---:|---:|---:|---:|---:|"]
for a,nm in names.items():
    va=ds["arms"][a];st=ds["storage"][a];ms=sum(tm["transition_ns"][a] for tm in times)/ev/1e6
    notes.append(f"| {nm} | {va['hits']}/{n} ({pct(va['hits']/n)}%) | {pct(va['fraction'])}% | {va['start']} | {int(round(st['mean']))} / {st['maximum']} | {dec(ms)} |")
notes+=["","*Среднее настенное время на переход в перемежающемся многопроцессном запуске на одном компьютере. Включает чтение и повторное сжатие полного состояния, не является отдельным измерением производительности сервиса.","","| Парная разность по полному совпадению | п. п. | 95% интервал | Побед / поражений | Макро по репозиториям, п. п. |","|---|---:|---:|---:|---:|"]
for k in ["mixed-lru","mixed-typed","mixed-point","typed-lru","typed-point","point-lru"]:
    a,b=k.split("-");v=ds["contrasts"][k];lo,hi=v["ci"];notes.append(f"| {names[a]} минус {names[b]} | {dformat(v['delta'][0])} | [{dformat(lo[0])}, {dformat(hi[0])}] | {v['wins'][0]} / {v['losses'][0]} | {dformat(v['macro'][0])} |")
passed=all(ds["contrasts"]["mixed-"+a]["ci"][0][0]>0 for a in ("lru","typed"))
notes+=["",("Оба заранее поставленных сравнения пройдены." if passed else "Предварительный критерий улучшения одновременно над LRU и исходным графом не достигнут.")+" Интервалы рассчитаны 10 000 парными выборками с возвращением по проектам. На этой панели только восемь кластеров. В сравнении переключателя с LRU весь чистый выигрыш составили три дополнительные сохранённые правки. По одной пришлось на Astropy, Matplotlib и SymPy, пять репозиториев дали одинаковый результат. Дополнительная двусторонняя проверка знаков на трёх репозиториях с ненулевой разностью даёт p = 0,25. Это поясняет чувствительность интервала к выбору модели неопределённости. Число побед — срезы с полной правкой только у первой политики. Поскольку последовательность действий исходного агента всегда одна, улучшение здесь означало бы эффект на сохранность строк. Уровень решения задач и лидерборд SWE-bench данным запуском не измерялись.","","## По проектам","","| Проект | Срезов с правкой | LRU | Точечная | Граф | Переключатель |","|---|---:|---:|---:|---:|---:|"]
for p in projects:
    rr=[r for r in rows if r[1]==p];notes.append("| "+" | ".join([p,str(len(rr))]+[str(sum(r[-1][a][0] for r in rr)) for a in names])+" |")
notes+=["","## Аудит и воспроизведение","",f"В проекции {ev} событий. Лимит проверен {ev*4} раз, восстановление исторических снимков — {ds['audit']['checked_restore']} раз. Ветка LRU при переполнении одной общей памяти выбрана {gate['lru']} раз, граф {gate['typed']} раз. До оценки новой панели для неизменённых контролей побайтово воспроизведено {sum(read('control_audit.json')['exact_checkpoint_and_diagnostics_on_first_prior_issue_each_shard'].values())} прежних переходов на восьми других задачах, включая все диагностические значения. Сверено {con['common_lines']} нумерованных строк в двух родных полях траекторий. По независимой проверке новым текстом правки {ds['post_edit_validation']}.",f"Статусы источников {down['statuses']}. "+" ".join(r["id"]+" ("+r["status"]+")" for r in released),"","На входе были публичные записи SWE-agent 1.0 с Claude Sonnet 4. Оценка фиксированных политик работала на CPU, без новых вызовов LLM или запуска команд из траекторий. Модель вероятностей блоков и веса ширины целиком перенесены из SWE-smith. Новый выбор ветки — детерминированный. Будущие события не участвуют в выборе ветки.","","В этой папке PROTOCOL_RU.md, frozen_before_scoring.json и method_lock.json фиксируют дизайны и исходные реализации. selection_receipt.json, receipts.json и download_summary.json документируют отбор, URL и транспортные исключения. Предсказания и логи в cuts_*.jsonl.gz и events_*.jsonl.gz запечатаны до разметки. Построчные исходы в scored.jsonl.gz, доверительные интервалы и анализы чувствительности в results.json. Для повтора в исходной раскладке сначала select_followup.py (Python 3.12 и PyArrow), затем acquire_followup.py, generate.py, verify_controls.py, transfer_followup.py predict, transfer_followup.py grade, report.py. freeze.py предназначен для новой пустой рабочей папки до оценки.","","[Авторский запуск и ссылки на публичные траектории](https://github.com/SWE-bench/experiments/blob/40f164d5b8f1d249bf95a6df8b74b577fd8e519d/evaluation/verified/20250522_sweagent_claude-4-sonnet-20250514/README.md) · [Официальный набор Verified](https://huggingface.co/datasets/SWE-bench/SWE-bench_Verified/tree/78f471bf655a3137b2e8a75af1501690ec009ec3/data)"]
(D/"RESULTS_RU.md").write_text("\n".join(notes)+"\n",encoding="utf8")
print(n,ds["arms"],gate,down["statuses"])

